#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структура работы с задвижкойtypedef struct : public Queue_PRS  {  CShSensor sh;  bool  m_bP_IN;  bool  m_bP_AIR;  bool  m_bF_IN;  bool  m_bF_OUT;  bool  m_bF_AIR1;  bool  m_bF_AIR2;  bool  m_bF_VENT;  bool  m_bL_TOP;  bool  m_bL_BOTTOM;  bool  m_bL_AIR;  bool  m_bL_DRAINAGE;  bool bSocket;  } Queue_SensST;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~bool Is_Flag_Sensor ( int& Flag_State, int Flag ) { return ( Flag_State & Flag ) != 0; };// Функция отображенияint PaintSensST(DefinePaint)  {  QueueP(Queue_SensST);  //  CShSensor* sh=NULL;  if (p->nNumber!=-1)	sh = (CShSensor*)PipeSh;  else  if (p->nSocketNumber!=-1)	sh=(CShSensor*)q.m_pSocket->Sh(p->nSocketNumber);  //  if (sh==NULL)	  return 1;  if ( IsTypeOk )    {    if ( !p->m_bPressed )	{		  memcpy( &p->sh, sh, sizeof( CShSensor ) );		  p->m_bP_IN=Is_Flag_Sensor(p->sh.StatusZadv, ZADV_P_IN);		  p->m_bP_AIR=Is_Flag_Sensor(p->sh.StatusZadv, ZADV_P_AIR);		  p->m_bF_IN=Is_Flag_Sensor(p->sh.StatusZadv, ZADV_F_IN);		  p->m_bF_OUT=Is_Flag_Sensor(p->sh.StatusZadv, ZADV_F_OUT);		  p->m_bF_AIR1=Is_Flag_Sensor(p->sh.StatusZadv, ZADV_F_AIR1);		  p->m_bF_AIR2=Is_Flag_Sensor(p->sh.StatusZadv, ZADV_F_AIR2);		  p->m_bL_TOP=Is_Flag_Sensor(p->sh.StatusZadv, ZADV_L_TOP);		  p->m_bL_BOTTOM=Is_Flag_Sensor(p->sh.StatusZadv, ZADV_L_BOTTOM);		  p->m_bL_AIR=Is_Flag_Sensor(p->sh.StatusZadv, ZADV_L_AIR);		  p->m_bL_DRAINAGE=Is_Flag_Sensor(p->sh.StatusZadv, ZADV_L_DRAINAGE);		  p->m_bF_VENT=Is_Flag_Sensor(p->sh.StatusZadv, ZADV_F_VENT);	}    }  else  if ( ::GetMnemoStyle() & MNEMO_EDIT )    {    RECT rect = p->mRect;    ::InflateRect( &rect, -p->W()/4,  -p->H()/4 );    CMyPen   pen  ( hDC, COLORREF(0x80ff) );    CMyBrush brush( hDC, COLORREF(0x80ff) );    //pen.Rc( p->mRect );    pen.Ellipse( rect );    }  //  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~static void fnSendData(void* base,void* pVoid,bool bMessage)  {  ASS( base )  Queue_SensST* p = (Queue_SensST*)base;  if ( !ISTypeOK ) return;  //  bool bSend = true;  if ( bSend )    {    p->send.SetNew( pVoid );    p->pPipe->SendData( p->send, bMessage );    }  p->m_bPressed = !bMessage;  }void FillSens( SPriborBase* d, void* pp )  {	    d->fnData = fnSendData;		Queue_SensST* p = (Queue_SensST*)pp;		if ( d->pVoid == &p->sh.StatusZadv && lstrcmp( p->send.szValue, "P_IN" ) == 0 )			d->pVoid =  &p->m_bP_IN;		else		if ( d->pVoid == &p->sh.StatusZadv && lstrcmp( p->send.szValue, "P_AIR" ) == 0 )			d->pVoid =  &p->m_bP_AIR;		else		if ( d->pVoid == &p->sh.StatusZadv && lstrcmp( p->send.szValue, "F_IN" ) == 0 )			d->pVoid =  &p->m_bF_IN;		else		if ( d->pVoid == &p->sh.StatusZadv && lstrcmp( p->send.szValue, "F_OUT" ) == 0 )			d->pVoid =  &p->m_bF_OUT;		else		if ( d->pVoid == &p->sh.StatusZadv && lstrcmp( p->send.szValue, "F_AIR1" ) == 0 )			d->pVoid =  &p->m_bF_AIR1;		else		if ( d->pVoid == &p->sh.StatusZadv && lstrcmp( p->send.szValue, "F_AIR2" ) == 0 )			d->pVoid =  &p->m_bF_AIR2;		else		if ( d->pVoid == &p->sh.StatusZadv && lstrcmp( p->send.szValue, "L_TOP" ) == 0 )			d->pVoid =  &p->m_bL_TOP;		else		if ( d->pVoid == &p->sh.StatusZadv && lstrcmp( p->send.szValue, "L_BOTTOM" ) == 0 )			d->pVoid =  &p->m_bL_BOTTOM;		else		if ( d->pVoid == &p->sh.StatusZadv && lstrcmp( p->send.szValue, "L_AIR" ) == 0 )			d->pVoid =  &p->m_bL_AIR;		else		if ( d->pVoid == &p->sh.StatusZadv && lstrcmp( p->send.szValue, "L_DRAINAGE" ) == 0 )			d->pVoid =  &p->m_bL_DRAINAGE;		else		if ( d->pVoid == &p->sh.StatusZadv && lstrcmp( p->send.szValue, "F_VENT" ) == 0 )			d->pVoid =  &p->m_bF_VENT;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddSensST(DefineTegs)  {  //  AddQueueEx(Queue_SensST);  //  CShSensor sh;  memcpy( &p->sh, &sh, sizeof(CShSensor) );  p->pSH = &p->sh;  p->m_bP_IN=false;  p->m_bP_AIR=false;  p->m_bF_IN=false;  p->m_bF_OUT=false;  p->m_bF_AIR1=false;  p->m_bF_AIR2=false;  p->m_bL_TOP=false;  p->m_bL_BOTTOM=false;  p->m_bL_AIR=false;  p->m_bL_DRAINAGE=false;  p->m_bF_VENT=false;  char szSF[64] = "";  p->nSocketNumber=-1;  p->nNumber=-1;  p->bSocket=false;  //  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintSensST;  //    STegObj obj[] =    {    { 'S', "suff", szSF, 63 },	{ 'L', "socket", &p->bSocket },    // Дополнительная информация    EXT_QUEUE    };::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  int nActive = def.GetActiveObj();  if (p->bSocket)	  nActive = def.GetActiveObjSocket();    if ( *szSF )    {    const char* name = def.GetModelName(nActive);    char szName[128];    sprintf_s( szName, sizeof(szName), "%s%s", name, szSF );    def.AddKind(id_Sensor,szName);    def.m_queue.m_pPipe->End();	def.m_queue.m_pSocket->Refresh();    }	if (p->bSocket)		AddPribors( def, teg, Buffer, p, &FillSens, id_Sensor );	else		AddPriborsPipe( def, teg, Buffer, p, &FillSens, id_Sensor );    if ( *szSF )    {      def.m_queue.m_pPipe->m_nActive = nActive;	  def.m_queue.m_pSocket->m_nActive= nActive;    }  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~